end
end
end
if not lq then
return{why=eee[2355]}
end
return{seen=true,nums={stat=lq,loSeen=mq,hiSeen=nq,transformTo=iq},why=string.format(eee[2356],lq,tostring(mq),tostring(nq))}
end
return{seen=true,buff=eq,nums={maxSeen=fq.max,steps= #fq.vals,transformTo=iq},why=string.format(eee[2357],eq,tostring(fq.max))}
end
if No.family==eee[2121]then
local sq,tq,uq={},{},nil
for vq,wq in ipairs(Lo.steps)do
for xq,yq in pairs(wq.reset or{})do
table.insert(sq,yq)
table.insert(tq,wq.drop)
uq=uq or xq
