if#sq<3 then
return{why=eee[2358]}
end
return{seen=true,nums={atSeen=To(sq),hitSeen=To(tq),meter=uq},why=string.format(eee[2359],#sq)}
end
if No.family==eee[2090]then
return{why=eee[2360]}
end
return{why=eee[2361]}
