function pb.learn(zq)
local Aq={}
for Bq in pairs(zq.ids or{})do
local Cq,Dq=pcall(pb.guess,Bq)
for Eq,Fq in ipairs(Cq and type(Dq)==eee[1940]and Dq or{})do
if Fq.playable and not Fq.hand then
local Gq,Hq=pcall(pb.evidence,zq,Bq,Fq)
if Gq and type(Hq)==eee[1940]and Hq.seen then
local Iq=type(P.pasBook[Bq])==eee[1940]and P.pasBook[Bq]or{}
local Jq=type(Iq[Fq.pid])==eee[1940]and Iq[Fq.pid]or nil
local Kq={}
for Lq,Mq in pairs(Fq.nums or{})do
Kq[Lq]=Mq
end
for Nq,Oq in pairs(Hq.nums or{})do
Kq[Nq]=Oq
end
local Pq=Jq~=nil and Jq.family==Fq.family and(Jq.buff==nil or Hq.buff==nil or Jq.buff==Hq.buff)
Iq[Fq.pid]={family=Fq.family,name=Fq.name,nums=Kq,buff=Hq.buff or(Jq and Jq.buff),who=Hq.who or Fq.who,trigger=Fq.trigger,keyword=Fq.keyword,sure=(Pq and(tonumber(Jq.runs)or 0)>=1)and eee[2302]or eee[2362],runs=(Pq and(tonumber(Jq.runs)or 0)or 0)+1,at=os.time(),why=Hq.why}
P.pasBook[Bq]=Iq
table.insert(Aq,{id=Bq,g=Fq,e=Iq[Fq.pid]})
elseif Gq and type(Hq)==eee[1940]then
table.insert(Aq,{id=Bq,g=Fq,miss=Hq.why})
else
table.insert(Aq,{id=Bq,g=Fq,miss=eee[2363]..tostring(Hq)})
end
end
end
end
pb._model={}
return Aq
end
function pb.unexplained(Qq,Rq)
