for Yq,Zq in pairs(Qq.foeBuffs)do
if Zq.near>0 and Zq.first>=Qq.firstPlaced[Rq]-1 and not Sq[Yq]then
table.insert(Vq,{w=eee[2365],b=Yq,n=Zq.foes,max=Zq.max})
