function ib.bestInfinite()
local geb,heb
for ieb,jeb in ipairs(W.lastScored or{})do
if jeb.kind==eee[1959]and ib.eligible(jeb)then
local keb,leb=P.train.real[jeb.key],jeb.rec or W.rec(jeb.key)
local meb=(tonumber(leb.timed)or 0)>0 and leb.sec/leb.timed/60 or 0
local neb=(keb and keb.n>0 and meb>0)and(keb.sum/keb.n)/meb or 0
if neb<=0 then
neb=db.hiveTrainRate(jeb.key)or 0
end
if neb>(heb or 0)then
geb,heb=jeb,neb
end
end
end
return geb
end
function ib.ratio()
local oeb=P.train.cal
if not(oeb and(oeb.n or 0)>0 and(oeb.sim or 0)>0)then
return 1
end
return U.clamp(oeb.real/oeb.sim,0.05,2)
end
function ib.perRun(peb,qeb)
local reb=P.train.real[peb]
if reb and reb.n>0 then
return reb.sum/reb.n,true
end
local seb=db.hiveTrain(peb,qeb)
if seb then
return seb,true
end
local teb,ueb=0,0
local veb=W.isInf(peb)
for web,xeb in pairs(P.train.real)do
if W.isInf(web)==veb then
teb,ueb=teb+xeb.sum,ueb+xeb.n
end
end
if ueb>0 then
return teb/ueb,true
end
local yeb=P.trainSim[peb]
return yeb and yeb.tk and yeb.tk*ib.ratio()or nil,false
end
