gfb[Yeb[ffb].i]=Ueb
local hfb=gb.teamFrom(gfb,Peb.map)
local ifb=gb.run(Peb,hfb,{hpMul=Jeb,train=Deb.uuid})
if(Web and W.infTier(ifb.wave)>=Xeb)or(not Web and ifb.won)then
local jfb=gb.run(Peb,hfb,{hpMul=1,train=Deb.uuid})
local kfb=(jfb.tk or 0)/math.max(0.5,jfb.t/60)
