jb.ROOM_K_MAX=6
function jb.roomK(qjc)
local rjc=qjc~=nil and type(P.dg.roomK)==eee[1940]and P.dg.roomK[tostring(qjc)]or nil
return type(rjc)==eee[1940]and tonumber(rjc.k)or 1
end
function jb.applyK(sjc,tjc)
local ujc=jb.roomK(tjc)
if sjc and ujc>1 then
sjc.hpScale=(tonumber(sjc.hpScale)or 1)*ujc
sjc.roomK=ujc
end
return ujc
end
function jb.roomLearn(vjc)
if vjc or bb.kind~=eee[1960]or bb.roomLearned then
return
end
local wjc=P.dg.room
local xjc,yjc=bb.pred,bb.calRun
if type(wjc)~=eee[1940]or wjc.seed==nil or type(xjc)~=eee[1940]or not xjc.won or type(yjc)~=eee[1940]then
return
end
local function zjc(Ajc,Bjc)
return type(Ajc)==eee[1940]and tonumber(Ajc[Bjc]or Ajc[tostring(Bjc)])or nil
end
local Cjc={}
for Djc=2,bb.wave()do
local Ejc,Fjc=zjc(yjc.alive,Djc),zjc(xjc.aliveAt,Djc)
if Ejc and Fjc and Ejc>0 and Fjc>0 then
table.insert(Cjc,Ejc/Fjc)
end
end
if#Cjc<3 then
return
end
table.sort(Cjc)
local Gjc=Cjc[math.ceil(#Cjc/2)]
bb.roomLearned=true
if Gjc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==eee[1940]and P.dg.roomK or{}
local Hjc=tostring(wjc.seed)
local Ijc=P.dg.roomK[Hjc]
local Jjc=math.min(jb.ROOM_K_MAX,jb.roomK(Hjc)*Gjc)
P.dg.roomK[Hjc]={k=Jjc,n=(type(Ijc)==eee[1940]and tonumber(Ijc.n)or 0)+1,at=os.time(),d=wjc.d}
bb.roomKUp=true
local Kjc={}
for Ljc,Mjc in pairs(P.dg.roomK)do
table.insert(Kjc,{s=Ljc,at=type(Mjc)==eee[1940]and tonumber(Mjc.at)or 0})
end
table.sort(Kjc,function(Njc,Ojc)
return Njc.at>Ojc.at
end)
for Pjc=31,#Kjc do
P.dg.roomK[Kjc[Pjc].s]=nil
end
F.log(1,eee[3827],string.format(eee[3939],tostring(wjc.d),Gjc,Jjc))
end
function jb.roomDone(Qjc)
