local Flc,Glc={},0
for Hlc,Ilc in ipairs(workspace._UNITS:GetChildren())do
local Jlc=Ilc:FindFirstChild(eee[2003])
if Jlc and Jlc:FindFirstChild(eee[3956])and Jlc.player.Value==nil and Jlc:FindFirstChild(eee[3957])and Ilc:FindFirstChild(eee[3159])then
local Klc=tostring(Jlc.lane.Value)
if not Flc[Klc]then
Flc[Klc]=true
Glc=Glc+1
