local tmc
for umc,vmc in ipairs(smc and W.lastScored or{})do
if vmc.kind~=eee[1959]and(not tmc or(vmc.score or 0)>(tmc.score or 0))then
tmc=vmc
end
end
if not tmc or(tmc.score or 0)<=omc then
return
end
bb.stopping=true
F.log(1,eee[2601],string.format(eee[3968],gmc,omc,tmc.score,tmc.label))
bb.sellAll()
