KLc=KLc+1
if KLc%40==0 then
task.wait()
end
if OLc then
local PLc
if AJc then
PLc= -bb.cover(OLc,wKc)
elseif nKc then
PLc=0
local QLc=U.flat(OLc)
for RLc,SLc in ipairs(lKc)do
if(U.flat(SLc.pos)-QLc).Magnitude<=wKc then
PLc=PLc+(SLc.prog<=nKc+0.05 and 1 or 0.1)
end
end
elseif kLc then
PLc=0
local TLc=U.flat(OLc)
for ULc,VLc in ipairs(lKc)do
local WLc=(U.flat(VLc.pos)-TLc).Magnitude
if VLc.prog<kLc then
if WLc<=lLc then
PLc=PLc-2
end
elseif WLc<=wKc then
PLc=PLc+1
end
end
elseif uLc then
PLc=0
local XLc=U.flat(OLc)
for YLc,ZLc in ipairs(lKc)do
if(U.flat(ZLc.pos)-XLc).Magnitude<=wKc then
PLc=PLc+ZLc.prog*ZLc.prog
end
end
elseif yKc and qLc>0 then
local _Lc=0
for aMc,bMc in ipairs(pLc)do
local cMc=(U.flat(bMc.pos)-U.flat(OLc)).Magnitude
if cMc<=wKc then
_Lc=_Lc+bMc.dps*(1.1-0.1*cMc/math.max(1,wKc))
end
end
PLc=_Lc/qLc*100+bb.cover(OLc,wKc,true)*0.05
else
local dMc=bb.cover(OLc,wKc,true,kKc)
if xKc then
dMc=bb.cover(OLc,xKc)+dMc*0.25
end
PLc=dMc+(LLc and 0 or(1-bb.progressAt(OLc))*0.5)
local eMc=0
for fMc,gMc in ipairs(oLc)do
local hMc=gMc.b.types[nLc]
if hMc and(U.flat(gMc.pos)-U.flat(OLc)).Magnitude<=gMc.range then
eMc=math.max(eMc,math.min(hMc,eMc+hMc*gMc.b.uptime))
end
end
PLc=PLc*(1+eMc)
end
if vLc and(U.flat(vLc)-U.flat(OLc)).Magnitude<=wLc then
PLc=PLc+1e6
end
if xLc and(U.flat(xLc)-U.flat(OLc)).Magnitude<=yLc then
PLc=PLc+1e6
end
if zLc then
table.insert(zLc,{p=OLc,sc=PLc})
end
if not ILc or PLc>ILc then
HLc,ILc,JLc=OLc,PLc,bb.cover(OLc,wKc)
end
end
end
if yKc and#pLc>0 and HLc then
local iMc=false
for jMc,kMc in ipairs(pLc)do
if(U.flat(kMc.pos)-U.flat(HLc)).Magnitude<=wKc then
iMc=true
break
end
end
if not iMc then
return nil,0
end
end
if zLc and#zLc>0 then
table.sort(zLc,function(lMc,mMc)
return lMc.sc>mMc.sc
end)
for nMc=1,math.min(15,#zLc)do
local oMc,pMc=zLc[nMc].p,0
for qMc=0,7 do
local rMc=qMc*math.pi/4
if bb.valid(oMc+Vector3 .new(math.cos(rMc),0,math.sin(rMc))*5,jKc)then
pMc=pMc+1
end
if pMc>=2 then
break
end
end
if pMc>=2 then
return oMc,bb.cover(oMc,wKc)
end
end
end
return HLc,JLc or 0
end
function bb.lookAt(sMc)
local tMc,uMc=math.huge,nil
for vMc,wMc in ipairs(bb.samples)do
local xMc=(U.flat(wMc.pos)-U.flat(sMc)).Magnitude
if xMc<tMc then
tMc,uMc=xMc,wMc.pos
end
end
local yMc=uMc and U.flat(uMc-sMc)or Vector3 .new(0,0,-1)
return yMc.Magnitude>0.01 and yMc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(zMc,AMc)
